# ----------------------------------------------------------------------
# Section: deSolve
# ----------------------------------------------------------------------
set.seed(20260731)
library(deSolve)

mod <- function(t, y, parms) {
  with(as.list(c(y, parms)), {
    dA1 <- -k12 * A1 + k21 * A2 - k10 * A1
    dA2 <- k12 * A1 - k21 * A2
    list(c(dA1, dA2))
  })
}
y0 <- c(A1 = 100, A2 = 0)
out <- ode(y0, times = seq(0, 24, 0.1), mod,
           parms = c(k10 = 0.08, k12 = 0.2, k21 = 0.15))
head(out)

# ----------------------------------------------------------------------
# Section: rxode2
# ----------------------------------------------------------------------
set.seed(20260731)
library(rxode2)

mod <- rxode2({
  d/dt(cent) = -(CL/V) * cent
  cp = cent / V
})
ev <- et(amt = 500, cmt = 1)
ev <- et(ev, seq(0, 24, 0.25))
x <- rxSolve(mod, params = c(CL = 5, V = 50), events = ev)
head(as.data.frame(x))

# ----------------------------------------------------------------------
# Section: mrgsolve
# ----------------------------------------------------------------------
set.seed(20260731)
library(mrgsolve)

code <- '
$PARAM CL = 5, V = 50, KA = 0.5
$CMT GUT CENT
$MAIN
double ke = CL/V;
$ODE
dxdt_GUT  = -KA*GUT;
dxdt_CENT =  KA*GUT - ke*CENT;
$TABLE
double cp = CENT/V;
$CAPTURE cp
'
mod <- mcode("oral1", code, quiet = TRUE)
out <- mod |> ev(amt = 500, cmt = 1) |> mrgsim(end = 24, delta = 0.25)
head(as.data.frame(out))

