# ----------------------------------------------------------------------
# Section: ggplot2 PK Plots
# ----------------------------------------------------------------------
set.seed(20260731)
library(dplyr)
library(ggplot2)

dat <- tibble(
  TIME = rep(c(0, 1, 2, 4, 8), 3),
  DV = c(0, 7, 6.5, 4, 2, 0, 8, 7, 5, 2.5, 0, 9, 8, 6, 3),
  ID = rep(1:3, each = 5)
)

ggplot(dat |> filter(DV > 0), aes(TIME, DV, color = factor(ID))) +
  geom_line() + geom_point() +
  scale_y_log10() +
  labs(x = "Time (h)", y = "Concentration (mg/L)") +
  theme_minimal()

# Observed vs predicted (popPK GOF)
ggplot(dat, aes(DV, DV * runif(nrow(dat), 0.9, 1.1))) +
  geom_point() +
  geom_abline(slope = 1, intercept = 0, linetype = 2) +
  labs(x = "Observed", y = "Predicted") +
  theme_minimal()

